// кейсы .qa/tests/admin/AD-01, AD-02. Тикет #a5decf4a · a5decf4a9de744b22c38c93f. Решение пользователя 07.10: админка есть и в приложении — у аккаунта клиента (ADMIN).
// Опора: «מה נדרש» — управление только у админа; реджект 05.10 «вход только по URL /admin» → решение 05.10: вход из профиля «ניהול ← ממשק ניהול התוכן».
// Только просмотр. В конце — вернуть USER1. TODO калибровка: если в приложении точка входа иная — правка в specs/_lib/admin.ts (openAdminHome).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, tapLabel, scrollToText, swipeUp } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { asAdmin, backToUser1, openAdminHome, scrollToMatch, cardRe } from '../_lib/admin.ts';

describe('Админка в приложении: доступ', () => {
  afterEach(async () => { await toHome(); });

  it('AD-01/AD-02 USER1 не видит «ממשק ניהול התוכן»; ADMIN видит «ניהול» и открывает «ניהול תכני תפילה» #a5decf4a @prod-safe', async () => {
    try {
      // 1. USER1: профиль → до конца экрана — нет раздела «ניהול» и строки «ממשק ניהול התוכן».
      await toHome();
      await tapLabel('מעבר לפרטים שלי');
      await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
      await scrollToText('התנתקות');                                   // низ профиля — всё пролистано
      await expect(byText('ממשק ניהול התוכן')).not.toBeDisplayed();
      await expect(byText('מנהל תוכן')).not.toBeDisplayed();
      await expect(byText('ניהול תכני תפילה')).not.toBeDisplayed();

      // 2. ADMIN: профиль → раздел «ניהול», строка «ממשק ניהול התוכן» с подписью «מנהל תוכן».
      await asAdmin();
      await tapLabel('מעבר לפרטים שלי');
      await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
      await scrollToText('ממשק ניהול התוכן');
      await expect(byText('ניהול')).toBeDisplayed();
      await expect(byText('מנהל תוכן')).toBeDisplayed();

      // 3. Нажать → «ניהול תכני תפילה», «שלום, …», разделы «תפילות היום» и «תפילות ומקטעים לזמנים מיוחדים» (AD-01/AD-03).
      await openAdminHome();
      await expect(byTextMatches('שלום, .+')).toBeDisplayed();
      await expect(byText('תפילות היום')).toBeDisplayed();
      await expect(await scrollToMatch(cardRe('ערבית', 'אשכנז'))).toBeDisplayed();
      await expect(byTextMatches('\\d+ מתוך 15 קטעים מאושרים')).toBeDisplayed();
      await swipeUp();
      await expect(await scrollToText('תפילות ומקטעים לזמנים מיוחדים')).toBeDisplayed();
      await expect(byTextContains('קטעים מאושרים')).toBeDisplayed();
    } finally {
      await backToUser1();
    }
  });
});
